  private buckets = new Map<string, { count: number; resetAt: number }>();
  constructor(private cleanupIntervalMs = 60000) { start interval; unref? }
  async consume(key, limit, windowMs) {
    const now = Date.now();
    const bucket = this.buckets.get(key);
    if (!bucket || now >= bucket.resetAt) {
      if (bucket) this.buckets.delete(key);
      this.buckets.set(key, { count:1, resetAt: now+windowMs});
      return { allowed: true, remaining: limit-1, retryAfterMs:0, resetAt: now+windowMs, limit };
    }
    if (bucket.count >= limit) {
      return { allowed:false, remaining:0, retryAfterMs: bucket.resetAt - now, resetAt: bucket.resetAt, limit };
    }
    bucket.count++;
    return { allowed:true, remaining: limit-bucket.count, retryAfterMs:0, resetAt: bucket.resetAt, limit };
  }
}

